# The order-48 recurrence in the OEIS FORMULA field, as RHS coefficients for
# a(n-d), d=1,...,48.  The omitted d=24 coefficient is zero.
RHS = [
    5, -5, 4, -3, -49, 10, 15, 45, 124, 131, 301, 18, -615, -201,
    -1508, -823, -413, -254, 2467, 793, 4516, 1071, 2289, 0, -2289,
    -1071, -4516, -793, -2467, 254, 413, 823, 1508, 201, 615, -18,
    -301, -131, -124, -45, -15, -10, 49, 3, -4, 5, -5, 1,
]
assert len(RHS) == 48


def bit(row, j):
    return (row >> j) & 1


def eqbit(x, y):
    return int(x == y)


def horizontal_equal(row, j):
    total = 0
    if j > 0:
        total += eqbit(bit(row, j - 1), bit(row, j))
    if j + 1 < 4:
        total += eqbit(bit(row, j + 1), bit(row, j))
    return total


def boundary(row, vertical):
    return all(horizontal_equal(row, j) + eqbit(bit(vertical, j), bit(row, j)) != 2
               for j in range(4))


def interior(prev, row, nxt):
    return all(horizontal_equal(row, j)
               + eqbit(bit(prev, j), bit(row, j))
               + eqbit(bit(nxt, j), bit(row, j)) != 2
               for j in range(4))


def legal_board(rows):
    if rows[0] & 1:
        return False
    for i, row in enumerate(rows):
        for j in range(4):
            equal = horizontal_equal(row, j)
            if i > 0:
                equal += eqbit(bit(rows[i - 1], j), bit(row, j))
            if i + 1 < len(rows):
                equal += eqbit(bit(rows[i + 1], j), bit(row, j))
            if equal == 2:
                return False
    return True


def exhaustive_count(n):
    # The first row-major bit is fixed to zero; all other entries vary.
    return sum(legal_board(rows) for rows in product(range(16), repeat=n)
               if not (rows[0] & 1))


def transfer_vectors():
    states = [(p, q) for p in range(16) for q in range(16)]
    vectors = []
    v0 = {state: int(boundary(state[1], state[0])) for state in states}
    vectors.append(v0)
    for _ in range(48):
        previous = vectors[-1]
        current = {}
        for p, q in states:
            current[(p, q)] = sum(
                int(interior(p, q, r)) * previous[(q, r)] for r in range(16)
            )
        vectors.append(current)
    return states, vectors


def transfer_total(vector):
    return sum(vector[(p, q)] for p in range(16) for q in range(16)
               if not (p & 1) and boundary(p, q))


def recurrence_rhs(values, n):
    # values is indexed by n-1, while n is the one-based source index.
    return sum(c * values[n - d - 1] for d, c in enumerate(RHS, start=1))


def main():
    assert len(OEIS) == 210

    # Fidelity: literal exhaustive boards at the four smallest heights.
    small = [exhaustive_count(n) for n in range(1, 5)]
    assert small == OEIS[:4] == [5, 10, 28, 99]

    # The transfer bridge reproduces all 49 values needed for the order-48
    # boundary case, and hence independently reproduces the displayed prefix.
    states, vectors = transfer_vectors()
    transfer_values = [OEIS[0]] + [transfer_total(vectors[k]) for k in range(48)]
    assert transfer_values == OEIS[:49]

    # Check the published recurrence on every available table term.
    for n in range(49, len(OEIS) + 1):
        assert OEIS[n - 1] == recurrence_rhs(OEIS, n), n

    # Exact annihilation certificate on all 256 row-pair states.  The
    # descending polynomial coefficients are [1] + [-RHS in reverse order].
    coeff = [1] + [-c for c in RHS]
    assert len(coeff) == 49
    residuals = {
        state: sum(coeff[j] * vectors[48 - j][state] for j in range(49))
        for state in states
    }
    assert len(states) == 256
    assert sum(int(interior(p, q, r)) for p, q, r in product(range(16), repeat=3)) == 626
    assert all(value == 0 for value in residuals.values())

    # The n=49 boundary residual follows from the same 49 exact values.
    assert OEIS[48] == recurrence_rhs(OEIS, 49)

    print("small_counts", small)
    print("states", len(states), "edges", 626)
    print("annihilator_residuals", len(residuals), "all_zero", all(v == 0 for v in residuals.values()))
    print("oeis_terms_checked", len(OEIS), "recurrence_indices", "49..210")
    print("ALL_CHECKS_OK")


if __name__ == "__main__":
    main()
